// Packages: AWSSDK.CloudWatch, Amazon.CloudWatch
using Amazon.CloudWatch;
using Amazon.CloudWatch.Model;

public class CloudWatchMetricsService
{
    private readonly IAmazonCloudWatch _cloudWatch;
    private const string Namespace = "AspNetCore/MyApp";

    public CloudWatchMetricsService(IAmazonCloudWatch cloudWatch)
    {
        _cloudWatch = cloudWatch;
    }

    public async Task PublishOrderCountAsync(int orderCount, string environment, CancellationToken cancellationToken = default)
    {
        try
        {
            var putMetricRequest = new PutMetricDataRequest
            {
                Namespace = Namespace,
                MetricData = new List<MetricDatum>
                {
                    new MetricDatum
                    {
                        MetricName = "OrderCount",
                        Value = orderCount,
                        Unit = StandardUnit.Count,
                        Timestamp = DateTime.UtcNow,
                        Dimensions = new List<Dimension>
                        {
                            new Dimension { Name = "Environment", Value = environment }
                        }
                    }
                }
            };

            PutMetricDataResponse response = await _cloudWatch.PutMetricDataAsync(putMetricRequest, cancellationToken);
            Console.WriteLine($"Published {orderCount} orders to CloudWatch (RequestId: {response.ResponseMetadata.RequestId})");
        }
        catch (AmazonCloudWatchException ex)
        {
            Console.WriteLine($"CloudWatch error: {ex.Message}");
            throw;
        }
    }
}

