// Packages: AWSSDK.CloudWatch, Amazon.CloudWatch (for direct log sending if needed)
using Microsoft.Extensions.Logging;

public class PostsController : ControllerBase
{
    private readonly ILogger<PostsController> _logger;
    private readonly BlogContext _db;

    public PostsController(ILogger<PostsController> logger, BlogContext db)
    {
        _logger = logger;
        _db = db;
    }

    [HttpGet("{id}")]
    public async Task<ActionResult<Post>> Get(int id, CancellationToken cancellationToken)
    {
        using var _ = _logger.BeginScope(new Dictionary<string, object>
        {
            ["PostId"] = id,
            ["Controller"] = nameof(PostsController)
        });

        _logger.LogInformation("Fetching post {PostId} from RDS", id);

        Post? post;
        try
        {
            post = await _db.Posts.FindAsync([id], cancellationToken: cancellationToken);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Database error fetching post {PostId}", id);
            throw;
        }

        if (post is null)
        {
            _logger.LogWarning("Post {PostId} not found", id);
            return NotFound();
        }

        _logger.LogInformation("Returning post {PostId}: {Title}", id, post.Title);
        return Ok(post);
    }
}

// Usage:
// GET /posts/1
// Logs appear in CloudWatch Logs with structured fields: PostId=1, Controller=PostsController
// CloudWatch Logs Insights query: fields @timestamp, PostId, @message | filter PostId = 1
